def quote(weight, express=False):
    if weight <= 0:
        raise ValueError("positive weight required")
    base = 100 if weight <= 5 else 200
    return base + (50 if express else 0)

fixed_fixture_files.tests/test_app.py:
import unittest
from app import quote

class QuoteTest(unittest.TestCase):
    def test_normal(self):
        self.assertEqual(quote(3), 100)
    def test_boundary(self):
        self.assertEqual(quote(5), 100)
        self.assertEqual(quote(6), 200)
    def test_express(self):
        self.assertEqual(quote(6, True), 250)
    def test_invalid(self):
        with self.assertRaises(ValueError):
            quote(0)

